package lk.repairdesk.api.domain; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="quotations") @Getter @Setter @NoArgsConstructor public class Quotation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private RepairRequest repairRequest; @Column(nullable=false,precision=12,scale=2) private BigDecimal labourCost; @Column(nullable=false,precision=12,scale=2) private BigDecimal partsCost; @Column(nullable=false,precision=12,scale=2) private BigDecimal tax; @Column(nullable=false) private LocalDate validUntil; @Enumerated(EnumType.STRING) @Column(nullable=false) private QuotationStatus status=QuotationStatus.PENDING; @Column(length=1000) private String notes; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); public BigDecimal total(){return labourCost.add(partsCost).add(tax);} }
